<template><div class="page"><div class="page-head"><div><h2>巡检配置</h2><p>维护巡检类型、动态表单、执行频率与设备范围。</p></div><el-button v-if="tab==='plan'" type="primary" @click="generate">立即生成到期任务</el-button></div>
<el-tabs v-model="tab" class="card">
 <el-tab-pane label="巡检类型" name="type"><div class="toolbar"><el-button type="primary" @click="editType()">新增类型</el-button></div><el-table :data="types"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column prop="targetCategory" label="对象类别"/><el-table-column prop="description" label="说明"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="editType(s.row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane>
 <el-tab-pane label="巡检表单" name="template"><div class="toolbar"><el-button type="primary" @click="editTemplate()">新增表单</el-button></div><el-table :data="templates"><el-table-column prop="name" label="表单名称"/><el-table-column prop="inspectionTypeName" label="巡检类型"/><el-table-column prop="versionNo" label="版本" width="80"/><el-table-column label="巡检项"><template #default="s">{{parseFields(s.row.fieldsJson).length}} 项</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="editTemplate(s.row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane>
 <el-tab-pane label="巡检计划" name="plan"><div class="toolbar"><el-button type="primary" @click="editPlan()">新增计划</el-button></div><el-table :data="plans"><el-table-column prop="name" label="计划名称" min-width="150"/><el-table-column prop="inspectionTypeName" label="类型"/><el-table-column prop="templateName" label="表单"/><el-table-column label="频率"><template #default="s">{{frequencyText(s.row)}}</template></el-table-column><el-table-column prop="executeTime" label="执行时间"/><el-table-column prop="targetCount" label="设备数" width="80"/><el-table-column label="责任归属" min-width="170"><template #default="s">{{ownerText(s.row)}}</template></el-table-column><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="editPlan(s.row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane>
</el-tabs>
<el-dialog v-model="typeVisible" title="巡检类型" width="520"><el-form label-width="90"><el-form-item label="类型编码"><el-input v-model="typeForm.code"/></el-form-item><el-form-item label="类型名称"><el-input v-model="typeForm.name"/></el-form-item><el-form-item label="对象类别"><el-select v-model="typeForm.targetCategory"><el-option label="设备" value="DEVICE"/><el-option label="区域" value="AREA"/><el-option label="通用" value="ALL"/></el-select></el-form-item><el-form-item label="说明"><el-input v-model="typeForm.description" type="textarea"/></el-form-item><el-form-item label="启用"><el-switch v-model="typeForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="typeVisible=false">取消</el-button><el-button type="primary" @click="saveType">保存</el-button></template></el-dialog>
<el-dialog v-model="templateVisible" title="动态巡检表单" width="900"><el-form label-width="90"><el-form-item label="表单名称"><el-input v-model="templateForm.name"/></el-form-item><el-form-item label="巡检类型"><el-select v-model="templateForm.inspectionTypeId"><el-option v-for="x in types" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item></el-form><div class="subhead"><b>巡检项目</b><el-button @click="addField">增加一项</el-button></div><div v-for="(f,i) in templateForm.fields" :key="i" class="field-row"><el-input v-model="f.label" placeholder="项目名称"/><el-select v-model="f.controlType"><el-option label="正常/异常" value="RADIO"/><el-option label="数值" value="NUMBER"/><el-option label="文本" value="TEXT"/><el-option label="下拉选择" value="SELECT"/><el-option label="拍照" value="PHOTO"/></el-select><el-input v-model="f.unit" placeholder="单位"/><el-checkbox v-model="f.required">必填</el-checkbox><el-checkbox v-model="f.photoRequired">异常需拍照</el-checkbox><el-button type="danger" link @click="templateForm.fields.splice(i,1)">删除</el-button></div><template #footer><el-button @click="templateVisible=false">取消</el-button><el-button type="primary" @click="saveTemplate">保存</el-button></template></el-dialog>
<el-dialog v-model="planVisible" title="巡检计划" width="850"><el-form :model="planForm" label-width="100"><el-row :gutter="16"><el-col :span="12"><el-form-item label="计划名称"><el-input v-model="planForm.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="巡检类型"><el-select v-model="planForm.inspectionTypeId" @change="planForm.templateId=null"><el-option v-for="x in types.filter((x:any)=>x.enabled)" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="表单模板"><el-select v-model="planForm.templateId"><el-option v-for="x in templates.filter((x:any)=>x.inspectionTypeId===planForm.inspectionTypeId)" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="执行频率"><el-select v-model="planForm.frequencyType"><el-option label="每天" value="DAILY"/><el-option label="每周" value="WEEKLY"/><el-option label="每月" value="MONTHLY"/><el-option label="间隔天数" value="INTERVAL_DAYS"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="频率间隔"><el-input-number v-model="planForm.frequencyValue" :min="1"/></el-form-item></el-col><el-col :span="12"><el-form-item label="执行时间"><el-time-picker v-model="planForm.executeTime" value-format="HH:mm:ss"/></el-form-item></el-col><el-col :span="12"><el-form-item label="开始日期"><el-date-picker v-model="planForm.startDate" type="date" value-format="YYYY-MM-DD"/></el-form-item></el-col><el-col :span="12"><el-form-item label="结束日期"><el-date-picker v-model="planForm.endDate" type="date" value-format="YYYY-MM-DD" clearable/></el-form-item></el-col><el-col :span="12"><el-form-item label="逾期分钟"><el-input-number v-model="planForm.overdueMinutes" :min="30"/></el-form-item></el-col><el-col :span="12"><el-form-item label="任务分类"><el-select v-model="planForm.category"><el-option label="日常事务" value="DAILY"/><el-option label="安全消防" value="SAFETY"/><el-option label="保洁环境" value="CLEANING"/><el-option label="运营管理" value="OPERATION"/><el-option label="会议培训" value="MEETING"/><el-option label="其他" value="OTHER"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="回执模式"><el-select v-model="planForm.formMode"><el-option label="清单回执" value="CHECKLIST"/><el-option label="仅确认" value="NONE"/><el-option label="巡检表单" value="INSPECTION"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="强制拍照"><el-switch v-model="planForm.requirePhoto" :active-value="1" :inactive-value="0"/></el-form-item></el-col><el-col :span="12"><el-form-item label="提前推送(分)"><el-input-number v-model="planForm.advanceMinutes" :min="0"/></el-form-item></el-col><el-col :span="12"><el-form-item label="催办间隔(分)"><el-input-number v-model="planForm.urgeMinutes" :min="0"/></el-form-item></el-col><el-col :span="12"><el-form-item label="归属类型"><el-select v-model="planForm.ownerType" @change="onOwnerTypeChange"><el-option label="个人任务" value="USER"/><el-option label="岗位任务" value="ROLE"/><el-option label="部门任务" value="DEPT"/></el-select></el-form-item></el-col><el-col :span="12" v-if="planForm.ownerType==='USER'"><el-form-item label="负责人"><el-select v-model="planForm.ownerId" filterable clearable placeholder="选择执行人" @change="syncAssignee"><el-option v-for="u in ownerOptions.users" :key="u.id" :label="u.name" :value="u.id"/></el-select></el-form-item></el-col><el-col :span="12" v-else-if="planForm.ownerType==='ROLE'"><el-form-item label="责任岗位"><el-select v-model="planForm.ownerId" filterable placeholder="选择岗位/角色"><el-option v-for="r in ownerOptions.roles" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item></el-col><el-col :span="12" v-else><el-form-item label="责任部门"><el-tree-select v-model="planForm.ownerId" :data="deptTree" :props="{label:'label',children:'children'}" node-key="value" check-strictly :render-after-expand="false" placeholder="选择部门"/></el-form-item></el-col><el-col :span="12" v-if="planForm.ownerType==='DEPT'"><el-form-item label="下发方式"><el-select v-model="planForm.targetMode"><el-option label="部门整体一次" value="UNIT"/><el-option label="按子部门各一次" value="PER_CHILD"/></el-select></el-form-item></el-col><el-col :span="12" v-if="planForm.ownerType!=='USER'"><el-form-item label="认领方式"><el-select v-model="planForm.claimMode"><el-option label="需认领" value="CLAIM"/><el-option label="无需认领" value="NONE"/><el-option label="自动指派（单人岗位）" value="AUTO"/></el-select></el-form-item></el-col></el-row><el-form-item label="巡检设备" v-if="!(planForm.ownerType==='DEPT'&&planForm.targetMode==='PER_CHILD')"><el-select v-model="selectedTargetIds" multiple filterable remote :remote-method="searchTargets" style="width:100%" placeholder="输入设备名称、ID、序列号搜索"><el-option v-for="x in targetOptions" :key="x.targetId" :label="`${x.targetName}（${x.targetCode}）`" :value="x.targetId"/></el-select><div class="hint">已选择 {{selectedTargetIds.length}} 台设备</div></el-form-item><el-form-item label="巡检设备" v-else><div class="hint">按子部门下发时，每个直属子部门各生成一条任务，不需要选择设备。</div></el-form-item><el-form-item label="通知机器人"><el-select v-model="planForm.webhookConfigIds" multiple clearable style="width:100%" placeholder="可选择一个或多个机器人"><el-option v-for="x in webhooks.filter((x:any)=>x.enabled===1)" :key="x.id" :label="x.name" :value="x.id"/></el-select><div class="hint">任务到期前两小时和逾期时发送通知；不选择则按 Webhook 订阅规则发送。</div></el-form-item><el-form-item label="启用"><el-switch v-model="planForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="planVisible=false">取消</el-button><el-button type="primary" @click="savePlan">保存并生成任务</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">import{ref,computed,onMounted}from'vue';import{ElMessage}from'element-plus';import{inspectionApi}from'@/api/inspection';import{webhookApi}from'@/api/webhook';
const tab=ref('plan'),types=ref<any[]>([]),templates=ref<any[]>([]),plans=ref<any[]>([]),webhooks=ref<any[]>([]),ownerOptions=ref<any>({departments:[],roles:[],users:[]});const typeVisible=ref(false),templateVisible=ref(false),planVisible=ref(false);const typeForm=ref<any>({}),templateForm=ref<any>({fields:[]}),planForm=ref<any>({}),targetOptions=ref<any[]>([]),selectedTargetIds=ref<string[]>([]);
const deptTree=computed(()=>{const nodes=(ownerOptions.value.departments||[]).map((d:any)=>({value:d.id,label:d.name,parentId:d.parentId,children:[] as any[]}));const map=new Map(nodes.map((n:any)=>[n.value,n]));const roots:any[]=[];nodes.forEach((n:any)=>{if(n.parentId&&map.has(n.parentId))(map.get(n.parentId) as any).children.push(n);else roots.push(n)});return roots});
const unwrap=(r:any)=>r?.data?.data??r?.data??r;function parseFields(s:any){try{return typeof s==='string'?JSON.parse(s):s||[]}catch{return[]}}async function load(){[types.value,templates.value,plans.value,ownerOptions.value]=await Promise.all([inspectionApi.types(),inspectionApi.templates(),inspectionApi.plans(),inspectionApi.ownerOptions()]).then(x=>x.map(unwrap))}
function ownerText(r:any){const type=r.ownerType||'USER';if(type==='ROLE')return `岗位：${r.ownerName||ownerOptions.value.roles?.find((x:any)=>x.id===r.ownerId)?.name||'-'}`;if(type==='DEPT'){const n=r.ownerName||ownerOptions.value.departments?.find((x:any)=>x.id===r.ownerId)?.name||'-';return `部门：${n}${r.targetMode==='PER_CHILD'?'（按子部门各一次）':''}`}return `个人：${r.ownerName||r.assigneeName||'-'}`}
function syncAssignee(id:any){const u=ownerOptions.value.users?.find((x:any)=>x.id===id);planForm.value.assigneeName=u?u.name:''}
function onOwnerTypeChange(t:string){planForm.value.ownerId=null;planForm.value.assigneeName='';planForm.value.targetMode='UNIT';planForm.value.claimMode=t==='USER'?'NONE':'CLAIM'}
function editType(r:any={}){typeForm.value={id:r.id,code:r.code||'',name:r.name||'',targetCategory:r.targetCategory||'DEVICE',description:r.description||'',enabled:r.id?!!r.enabled:true};typeVisible.value=true}async function saveType(){await inspectionApi.saveType(typeForm.value);ElMessage.success('已保存');typeVisible.value=false;load()}
function addField(){templateForm.value.fields.push({key:`item_${Date.now()}`,label:'',controlType:'RADIO',required:true,photoRequired:false,unit:''})}function editTemplate(r:any={}){templateForm.value={id:r.id,name:r.name||'',inspectionTypeId:r.inspectionTypeId,versionNo:r.versionNo||1,enabled:r.id?!!r.enabled:true,fields:parseFields(r.fieldsJson)};if(!templateForm.value.fields.length)addField();templateVisible.value=true}async function saveTemplate(){await inspectionApi.saveTemplate(templateForm.value);ElMessage.success('已保存');templateVisible.value=false;load()}
async function searchTargets(q=''){targetOptions.value=unwrap(await inspectionApi.targets(q))}async function editPlan(r:any={}){let webhookConfigIds:any[]=[];try{webhookConfigIds=typeof r.webhookConfigIds==='string'?JSON.parse(r.webhookConfigIds):r.webhookConfigIds||[]}catch{}const ownerType=r.ownerType||'USER';planForm.value={id:r.id,name:r.name||'',inspectionTypeId:r.inspectionTypeId,templateId:r.templateId,frequencyType:r.frequencyType||'DAILY',frequencyValue:r.frequencyValue||1,startDate:r.startDate||new Date().toISOString().slice(0,10),endDate:r.endDate||'',executeTime:String(r.executeTime||'09:00:00').slice(0,8),overdueMinutes:r.overdueMinutes||1440,ownerType,ownerId:r.ownerId??(ownerType==='USER'?ownerOptions.value.users?.find((x:any)=>x.name===r.assigneeName)?.id:null),targetMode:r.targetMode||'UNIT',claimMode:r.claimMode||(ownerType==='USER'?'NONE':'CLAIM'),formMode:r.formMode||'CHECKLIST',category:r.category||'OTHER',requirePhoto:r.requirePhoto?1:0,advanceMinutes:r.advanceMinutes??0,urgeMinutes:r.urgeMinutes??30,assigneeName:r.assigneeName||'',webhookConfigIds,enabled:r.id?!!r.enabled:true};targetOptions.value=(r.targets||[]).map((x:any)=>({...x}));selectedTargetIds.value=targetOptions.value.map(x=>x.targetId);planVisible.value=true;await searchTargets('')}
async function savePlan(){const f=planForm.value;f.targets=f.ownerType==='DEPT'&&f.targetMode==='PER_CHILD'?[]:selectedTargetIds.value.map(id=>{const x=targetOptions.value.find(y=>y.targetId===id);return{targetType:'INSPECTION_EQUIPMENT',targetId:id,targetCode:x?.targetCode||id,targetName:x?.targetName||id,locationText:x?.locationText||''}});if(f.ownerType==='USER'){const u=ownerOptions.value.users?.find((x:any)=>x.id===f.ownerId);f.assigneeName=u?u.name:''}else f.assigneeName='';await inspectionApi.savePlan(f);ElMessage.success('计划已保存');planVisible.value=false;load()}async function generate(){const r=unwrap(await inspectionApi.generate());ElMessage.success(`已生成 ${r.generated||0} 条任务`)}function frequencyText(r:any){return({DAILY:'每天',WEEKLY:`每${r.frequencyValue||1}周`,MONTHLY:`每${r.frequencyValue||1}月`,INTERVAL_DAYS:`每${r.frequencyValue||1}天`}as any)[r.frequencyType]||r.frequencyType}onMounted(async()=>{await Promise.all([load(),webhookApi.list().then(x=>webhooks.value=x)])})
</script><style scoped>.page{padding:20px}.page-head{display:flex;justify-content:space-between;align-items:center}.page-head h2{margin:0}.page-head p{color:#777;margin:6px 0 16px}.card{background:#fff;padding:16px;border-radius:8px}.toolbar{margin-bottom:12px}.subhead{display:flex;justify-content:space-between;margin:12px 0}.field-row{display:grid;grid-template-columns:1.5fr 1fr .7fr auto auto auto;gap:8px;align-items:center;margin-bottom:9px;padding:10px;background:#f6f8fa;border-radius:6px}.hint{color:#909399;font-size:12px;margin-top:5px}@media(max-width:768px){.page{padding:10px}.field-row{grid-template-columns:1fr}.page-head{align-items:flex-start}}</style>
